package com.training.accounting.auth; import com.training.accounting.user.AppUserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AppUserRepository ur;private final PasswordEncoder pe;private final JwtService js; public AuthController(AppUserRepository ur,PasswordEncoder pe,JwtService js){this.ur=ur;this.pe=pe;this.js=js;} public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest r){return ur.findByEmailIgnoreCase(r.email()).filter(u->u.isActive()&&pe.matches(r.password(),u.getPasswordHash())).<ResponseEntity<?>>map(u->ResponseEntity.ok(Map.of("token",js.createToken(u),"email",u.getEmail(),"role",u.getRole()))).orElseGet(()->ResponseEntity.status(401).body(Map.of("message","Invalid email or password")));} }
